-- Fine-tuning and public-weight model inventory researched 2026-07-12.
-- This file is a reproducible source mirror for the report tables. Hardware
-- figures are planning bands, not vendor guarantees; video length, frame count,
-- resolution, precision, attention implementation, and batch size can dominate.
--
-- Primary fine-tuning sources:
-- https://huggingface.co/docs/trl/v0.26.0/en/sft_trainer
-- https://huggingface.co/docs/peft/main/en/package_reference/lora
-- https://huggingface.co/docs/peft/developer_guides/quantization
-- https://github.com/QwenLM/Qwen3-VL/tree/main/qwen-vl-finetune
-- https://trec.nist.gov/pubs/trec34/papers/CERTH-ITI.avs.vqa.pdf
-- https://trec.nist.gov/pubs/trec34/papers/HLTCOE.vqa.pdf
-- https://trec.nist.gov/pubs/trec34/papers/NII_UIT.vqa.pdf

CREATE OR REPLACE VIEW finetuning_method_guide AS
SELECT * FROM (VALUES
  (1, 'Frozen baseline', 'No model weights', 'Prompt, frame/audio retrieval, evidence packing, and output rules', 'Always. It proves whether the model is failing or the evidence pipeline is failing.', 'Can hide a weak sampler behind a strong model name.'),
  (2, 'Ranker or task head only', 'A small judge, classifier, or listwise reranker', 'AG candidate ordering or MC option scoring after evidence and candidates already exist', 'Best first learned component when generation is adequate but ordering is weak.', 'Learns quirks of synthetic candidates or automatic labels if the training pool is narrow.'),
  (3, 'LoRA', 'Small low-rank adapter matrices; the base checkpoint stays frozen', 'Supervised fine-tuning of model behavior with much less optimizer state than a full update', 'Good first model adaptation when a repeated, task-specific error survives prompt and retrieval fixes.', 'Still needs clean examples and can overfit 500 videos; the adapter only works with the exact base family/revision.'),
  (4, 'QLoRA', 'LoRA adapters while the frozen base is loaded in 4-bit form', 'The same objectives as LoRA with lower base-weight memory', 'Preferred experiment when one GPU cannot hold a comfortable BF16 LoRA run.', 'Quantization, video activations, and long contexts still consume memory; training may be slower or less stable.'),
  (5, 'Full fine-tune', 'All or nearly all model weights', 'Large-scale domain adaptation after smaller methods plateau', 'Only with substantially more diverse data, multi-GPU operations, and evidence that adapters have saturated.', 'Highest cost and forgetting/overfitting risk; it does not repair missing frames, missing audio, bad labels, or leakage.')
) AS t(read_order, method, weights_updated, what_it_is_for, use_when, main_risk);

CREATE OR REPLACE VIEW finetuning_2025_evidence AS
SELECT * FROM (VALUES
  (1, 'CERTH-ITI', 'Multimodal model LoRA', 'Qwen2.5-Omni-7B; organizer 500-video training set; 10 frames / 1,024 visual tokens; 5 epochs; rank 16; alpha 64; one RTX 4090 24 GB', 'Their paper reports MC Top-1 73.2% frozen versus 74.4% after fine-tuning, and 76.1% when LoRA was combined with 10-view aggregation.', 'Participant-reported ablation, not an independent replication and not the same aggregation surface as the current 1,982-record appendix.'),
  (2, 'HLTCOE', 'Listwise reranker LoRA only', 'A small answer-ranking model; 500 samples split 90/10; 5 epochs; rank 16; alpha 32; dropout 0.05', 'Shows that the learned component can be the final judge rather than the expensive video generator.', 'The repository is incomplete and the private LoRA weights used for submission were not released.'),
  (3, 'NII_UIT', 'No backbone fine-tuning', 'Frozen Aria for AG and frozen InternVL for MC; improvements came from timestamped ASR, time-spaced frames, local tiles, and question-type prompting', 'A strong counterexample: evidence engineering can be the adaptation strategy when labels and compute are limited.', 'The public repository is reference code rather than a complete frozen reproduction of the submitted system.')
) AS t(read_order, team, what_was_trained, published_recipe, reported_lesson, evidence_limit);

CREATE OR REPLACE VIEW finetuning_data_requirements AS
SELECT * FROM (VALUES
  (1, 'Pipeline smoke set', '100–500 carefully checked examples', 'video_id + question + exact evidence pack + desired answer/output shape', 'Use to verify decoding, token masking, batching, loss decrease, checkpoint loading, and schema output. It is not enough to claim broad generalization.', 'Split by video and source before creating QA rows.'),
  (2, 'First useful adapter experiment', 'About 1,000–5,000 diverse examples is a practical starting band', 'Grounded supervised examples spanning duration, question type, visible text, speech, non-speech audio, and failure cases', 'Track learning curves; stop adding epochs when validation stalls. Example quality and coverage matter more than hitting a number.', 'No video, near-duplicate clip, movie, channel, or source family may cross train/validation/test.'),
  (3, 'AG candidate ranker', 'Hundreds to several thousand questions with 10–30 candidate answers each', 'question + evidence IDs/timestamps + candidate list + relevance/order labels', 'Include near-duplicates, plausible unsupported answers, and weak tail candidates. Measure top-1, top-5, and exact top-10 quality separately.', 'Generate candidates without seeing validation/test gold answers; document whether labels are human, scorer-derived, or synthetic.'),
  (4, 'MC option scorer', 'At least hundreds of balanced questions; more is safer across categories', 'question + evidence + all four untouched option strings + gold option', 'Randomly permute option order during training/evaluation and include no-video and shuffled-evidence controls.', 'A question and all of its option permutations stay in one split.'),
  (5, 'Evidence localization', 'A small high-quality slice can be more useful than many ungrounded answers', 'required timestamps, frames, crop boxes, transcript spans, or sound events attached to each answer', 'Use it to separate retrieval failure from reasoning failure and to supervise a selector or tool-calling policy.', 'Annotators must not infer an answer from outside knowledge when the evidence is absent.'),
  (6, 'Locked competition-style test', 'Large enough for per-category confidence intervals; never used for checkpoint choice', 'schema-valid AG and MC outputs plus latency, provenance, and evidence logs', 'Run once at decision gates. Keep the active 2026 evaluation material entirely outside training and tuning.', 'Freeze the test before the first training run; do not adapt after reading its scores.')
) AS t(read_order, training_asset, practical_scale, example_shape, quality_gate, split_rule);

CREATE OR REPLACE VIEW finetuning_hardware AS
SELECT * FROM (VALUES
  (1, 'Tiny video models: 0.25–2B', 'About 4–12 GB', 'About 8–16 GB', 'About 16–24 GB', 'Good for dataset, batching, masking, and schema smoke tests; not the assumed final accuracy ceiling.'),
  (2, 'Small models: 3–4B', 'About 10–16 GB', 'About 16–24 GB', 'About 24–48 GB', 'Best first serious adapter tier. Qwen3-VL-4B and InternVL3.5-4B fit this role.'),
  (3, 'Practical main models: 7–9B', 'About 18–48 GB', 'About 24–48 GB; 48–80 GB is more comfortable', 'About 48–80 GB', 'A 24 GB run is possible only with a tightly bounded recipe; CERTH reported 7B LoRA with 10 frames / 1,024 visual tokens on one RTX 4090.'),
  (4, 'Larger dense models: around 14B', 'About 32–48 GB or more', 'About 48–80 GB', '80 GB or multi-GPU', 'Use only after a smaller-model learning curve demonstrates a likely return; long video can move every estimate upward.'),
  (5, 'Full-model fine-tuning', 'Inference band depends on model', 'Not QLoRA: all trainable weights and optimizer states must fit', 'Usually multi-GPU even at moderate scale', 'Treat as a separate engineering project. Plan distributed training, checkpoint sharding, recovery, and substantially more storage.')
) AS t(read_order, model_tier, frozen_or_quantized_inference, qlora_planning_band, bf16_lora_planning_band, operational_note);

CREATE OR REPLACE VIEW open_model_inventory AS
SELECT * FROM (VALUES
  (1, 'Qwen/Qwen3-VL-4B-Instruct', '4B class', 'Apache-2.0; public and ungated', 'Video + image; no native audio', 'Official instruction checkpoint', 'One 24 GB-class GPU for bounded inference and first QLoRA experiments', 'Recommended primary starting point: modern temporal encoding, timestamp alignment, structured output, and manageable scale.'),
  (2, 'Qwen/Qwen3-VL-8B-Instruct', 'About 9B reported on Hub', 'Apache-2.0; public and ungated', 'Video + image; no native audio', 'Official instruction checkpoint', '24–48 GB inference; 48–80 GB adapter training is more comfortable', 'Stronger main model if the 4B learning curve justifies the cost. Prefer Instruct before Thinking for controllable output.'),
  (3, 'HuggingFaceTB/SmolVLM2-500M-Video-Instruct', '0.5B', 'Apache-2.0; public and ungated', 'Video + image; no native audio', 'Official video-instruction checkpoint', '4–8 GB inference; 8–12 GB adapter experiments', 'Fastest pipeline smoke test. The model card reports 1.8 GB for video inference, but accuracy is intentionally a low-cost baseline.'),
  (4, 'HuggingFaceTB/SmolVLM2-2.2B-Instruct', '2.2B class', 'Apache-2.0; public and ungated', 'Video + image; no native audio', 'Official instruction checkpoint', '8–12 GB inference; 16–24 GB adapter experiments', 'Best cheap fine-tuning sandbox; the model card reports about 5.2 GB video-inference memory and links a tutorial.'),
  (5, 'OpenGVLab/InternVL3_5-4B', 'About 4.7B total', 'Apache-2.0; public and ungated', 'Sampled video frames + dynamic high-resolution tiles; no native audio', 'Official post-trained checkpoint', 'One 24 GB-class GPU for bounded inference; 24–48 GB adapter training', 'Architecture-diverse comparison to Qwen; attractive for small objects, OCR, and tiled crops.'),
  (6, 'OpenGVLab/InternVL3_5-8B', 'About 8.5B total', 'Apache-2.0; public and ungated', 'Sampled video frames + tiles; no native audio', 'Official post-trained checkpoint', '24–48 GB inference; 48–80 GB adapter training', 'Suffixless checkpoint includes the lab post-training pipeline; the -Instruct variant is the cleaner SFT-only starting point.'),
  (7, 'DAMO-NLP-SG/VideoLLaMA3-2B', '2B', 'Apache-2.0; public and ungated', 'Video + image; no native audio', 'Official video-instruction checkpoint', '12–16 GB inference; about 24 GB adapter experiments', 'Low-cost video-native baseline with examples up to 128 frames; requires trust_remote_code and extra integration care.'),
  (8, 'DAMO-NLP-SG/VideoLLaMA3-7B', 'About 8B reported on Hub', 'Apache-2.0; public and ungated', 'Video + image; no native audio', 'Official video-instruction checkpoint', '24–48 GB inference; 48–80 GB adapter training', 'Useful architecture diversity and continuity with the 2025 field; custom code increases maintenance cost.'),
  (9, 'Qwen/Qwen2.5-VL-7B-Instruct', 'About 8B reported on Hub', 'Apache-2.0; public and ungated', 'Video + image with dynamic FPS/timestamps; no native audio', 'Official instruction checkpoint', '24–48 GB inference; 48–80 GB adapter training', 'Mature, well-supported baseline and common parent for public video-reasoning fine-tunes.'),
  (10, 'Qwen/Qwen2.5-Omni-7B', 'About 11B total reported on Hub', 'Apache-2.0 on current model card; public and ungated', 'Native video + speech + non-speech audio', 'Official multimodal assistant checkpoint', '48–80 GB for short/medium clips; longer clips can require more', 'Strong frozen audio-video expert. Native omni fine-tuning is more complex than adding ASR to a visual model.'),
  (11, 'lmms-lab/LLaVA-Video-7B-Qwen2', 'About 8B reported on Hub', 'Apache-2.0; public and ungated', 'Video, up to 64 frames in the model card; no native audio', 'Official research instruction checkpoint', '24–48 GB inference; 48–80 GB adapter training', 'Good historical/reproducibility baseline; newer temporal models are better first bets.'),
  (12, 'openbmb/MiniCPM-V-4_5', 'About 8.7B total', 'Apache-2.0; public and ungated', 'Video + image, including high-FPS use; no native audio', 'Official conversational/reasoning checkpoint', '32–48 GB inference; 48–80 GB adapter training', 'Efficiency/quality candidate when motion density matters; verify processor and thinking-output behavior against the schema.'),
  (13, 'openbmb/MiniCPM-o-4_5', 'About 9B', 'Apache-2.0; public and ungated', 'Native streaming audio + video', 'Official omni assistant checkpoint', 'About 48 GB inference; around 80 GB adapter experiments', 'Practical native-audio alternative to Qwen-Omni; keep frozen initially and use as an audio-video expert.'),
  (14, 'allenai/Molmo2-4B / allenai/Molmo2-8B', 'About 5B / 9B reported on Hub', 'Apache-2.0 weights; public and ungated', 'Video grounding, pointing, and tracking; no native audio', 'Official post-trained checkpoints', '24 GB for 4B; 24–48 GB for 8B inference', 'Excellent evidence-localization and counting specialist. Review the model card warning about some underlying dataset terms.'),
  (15, 'yanziang/InternVideo3-8B-Instruct', 'About 9B', 'Apache-2.0; public and ungated', 'Long video + temporal grounding; ASR is a tool rather than native audio', 'Primary-author Instruct + RL release', '48–80 GB inference; 80 GB or multi-GPU tuning', 'Promising June 2026 experimental watchlist model; integration references are still immature, so do not make it the first baseline.')
) AS t(read_order, checkpoint, parameter_scale, license_access, media_input, checkpoint_state, planning_hardware, competition_role_and_caveat);

CREATE OR REPLACE VIEW public_finetuned_models AS
SELECT * FROM (VALUES
  (1, 'Qwen/Qwen3-VL-4B-Thinking', 'Qwen3-VL-4B', 'Official reasoning post-training', 'Apache-2.0; public and ungated', 'Reasoning/evidence verifier after a controllable Instruct baseline', 'Long reasoning and tags complicate latency, exact JSON, and answer normalization.'),
  (2, 'OpenGVLab/InternVL3_5-8B-MPO', 'InternVL3.5-8B-Instruct', 'Official mixed preference optimization', 'Apache-2.0; public and ungated', 'Preference-optimized visual judge or comparison checkpoint', 'Very low current download/use evidence; validate the exact processor and output contract locally.'),
  (3, 'OpenGVLab/VideoChat-R1_5-7B', 'Qwen2.5-VL-7B', 'Video SFT + iterative perception/reasoning training', 'Apache-2.0; public and ungated', 'Evidence-interval search and revisiting selected clips', 'Oriented toward MC and verbose think/answer/glue output; use as an expert, not a drop-in final generator.'),
  (4, 'Video-R1/Video-R1-7B', 'Qwen2.5-VL-7B', 'Public video SFT + reinforcement learning', 'Apache-2.0; public and ungated', 'MC, OCR, and free-form video-reasoning experiments', 'Example uses 32 frames; chain-of-thought formatting must be removed and does not guarantee faithful evidence.'),
  (5, 'allenai/SAGE-MM-Molmo2-8B-SFT_RL', 'Molmo2-8B', 'Tool-use SFT + reinforcement learning', 'Apache-2.0; public and ungated', 'Decides when to call ASR, temporal grounding, high-resolution extraction, or analysis tools', 'Emits JSON actions and requires the SAGE runtime; it is an architecture reference or expert, not a drop-in VQA answerer.'),
  (6, 'DAMO-NLP-SG/VideoRefer-VideoLLaMA3-7B', 'VideoLLaMA3-7B-Image', 'Spatial-temporal grounding fine-tune', 'Apache-2.0; public and ungated', 'Object tracks, boxes, and targeted evidence crops', 'Specialist grounding weights, not a general AG/MC answer generator.'),
  (7, 'lmms-lab/LLaVA-NeXT-Video-7B-DPO', 'LLaVA-NeXT-Video-7B', 'Direct preference optimization', 'Llama 2 license; public and ungated', 'Older preference-tuned video baseline', 'Older stack and non-Apache base license; use mainly for historical comparison.'),
  (8, 'nvidia/Cosmos-Reason2-8B', 'Qwen3-VL-8B-Instruct', 'Physical/common-sense video reasoning fine-tune', 'Public page but automatic access gate; custom NVIDIA license', 'High-level physical reasoning expert', 'Not immediately downloadable without accepting access terms; verify license and output behavior before planning around it.'),
  (9, 'Team-specific 2025 LoRA adapters', 'CERTH Qwen2.5-Omni and HLTCOE reranker', 'Competition-specific LoRA', 'Not publicly released as reproducible submission checkpoints', 'Recipe inspiration only', 'Do not assume last year''s weights can be downloaded; reproduce the recipe with a pinned public base and your own split.')
) AS t(read_order, checkpoint, base_model, post_training, license_access, useful_role, main_caveat);
